SELECT (DATE_TRUNC('DAY', "STARTED_AT")) AS "TIME_BUCKET", (QUANTILE_CONT(ELAPSED_MS, 0.5)) AS "Q_P50_ELAPSED_MS" FROM (SELECT q."QUERY_ID" AS QUERY_ID, (TRY_CAST(q."START_TIME" AS TIMESTAMP)) AS STARTED_AT, q."WAREHOUSE_NAME" AS WAREHOUSE_NAME, q."WAREHOUSE_SIZE" AS WAREHOUSE_SIZE, q."USER_NAME" AS USER_NAME, q."ROLE_NAME" AS ROLE_NAME, q."DATABASE_NAME" AS DATABASE_NAME, q."QUERY_TYPE" AS QUERY_TYPE, q."EXECUTION_STATUS" AS EXECUTION_STATUS, q."ERROR_CODE" AS ERROR_CODE, q."QUERY_PARAMETERIZED_HASH" AS FINGERPRINT, (q."QUERY_TAG" ->> '$.team') AS QUERY_TAG_TEAM, q."TOTAL_ELAPSED_TIME" AS ELAPSED_MS, q."COMPILATION_TIME" AS COMPILATION_MS, q."EXECUTION_TIME" AS EXECUTION_MS, q."QUEUED_OVERLOAD_TIME" AS QUEUED_OVERLOAD_MS, q."QUEUED_PROVISIONING_TIME" AS QUEUED_PROVISIONING_MS, q."BYTES_SCANNED" AS BYTES_SCANNED, q."BYTES_SPILLED_TO_LOCAL_STORAGE" AS BYTES_SPILLED_LOCAL, q."BYTES_SPILLED_TO_REMOTE_STORAGE" AS BYTES_SPILLED_REMOTE, q."PARTITIONS_SCANNED" AS PARTITIONS_SCANNED, q."PARTITIONS_TOTAL" AS PARTITIONS_TOTAL, q."PERCENTAGE_SCANNED_FROM_CACHE" AS CACHE_FRACTION, (CAST(COALESCE(a."CREDITS_ATTRIBUTED_COMPUTE", 0) AS DECIMAL(38, 9))) AS CREDITS_ATTRIBUTED, (TRY_CAST(q."_LOADED_AT" AS TIMESTAMP)) AS LANDED_AT /* Landing time: its gap from STARTED_AT is this platform's own freshness. */, (q."_ACCOUNT") AS ACCOUNT_NAME /* Which account these rows came from. A stamped column OFFLINE, where one */ /* lake holds several accounts; the connection LIVE, where it is not in the */ /* data at all (see the ACCOUNT_OF shim). */ FROM query_history AS q LEFT JOIN query_attribution_history AS a ON a."QUERY_ID" = q."QUERY_ID") AS base GROUP BY (DATE_TRUNC('DAY', "STARTED_AT")) ORDER BY "Q_P50_ELAPSED_MS" DESC, "TIME_BUCKET" LIMIT 100
